begin;
create table public.engineering_revenue_projections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,work_id uuid not null,contract_id uuid not null,competence date not null,projected_amount numeric(18,2) not null check(projected_amount>=0),notes text,status text not null default 'active' check(status in('active','inactive')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,work_id) references public.works(tenant_id,company_id,id) on delete restrict,foreign key(tenant_id,company_id,contract_id) references public.engineering_contracts(tenant_id,company_id,id) on delete restrict,check(extract(day from competence)=1),unique(tenant_id,company_id,contract_id,competence));
create index engineering_revenue_projections_work_month_idx on public.engineering_revenue_projections(tenant_id,company_id,work_id,competence);create index engineering_revenue_projections_created_by_idx on public.engineering_revenue_projections(created_by) where created_by is not null;
alter table public.engineering_revenue_projections enable row level security;create policy engineering_revenue_projections_select on public.engineering_revenue_projections for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy engineering_revenue_projections_insert on public.engineering_revenue_projections for insert to authenticated with check(app_private.can_access_company(tenant_id,company_id));create policy engineering_revenue_projections_update on public.engineering_revenue_projections for update to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));create policy engineering_revenue_projections_delete on public.engineering_revenue_projections for delete to authenticated using(app_private.can_access_company(tenant_id,company_id));
create or replace function public.validate_engineering_revenue_projection() returns trigger language plpgsql set search_path='' as $$declare v_work uuid;v_balance numeric(18,2);v_other numeric(18,2);begin select work_id into v_work from public.engineering_contracts where tenant_id=new.tenant_id and company_id=new.company_id and id=new.contract_id;if v_work is null or v_work<>new.work_id then raise exception 'contract does not belong to selected work/company';end if;select gross_balance into v_balance from public.engineering_contract_financial_summary where tenant_id=new.tenant_id and company_id=new.company_id and contract_id=new.contract_id;select coalesce(sum(projected_amount),0) into v_other from public.engineering_revenue_projections where tenant_id=new.tenant_id and company_id=new.company_id and contract_id=new.contract_id and status='active' and id<>new.id;if new.status='active' and v_other+new.projected_amount>coalesce(v_balance,0) then raise exception 'future projections cannot exceed contract balance';end if;new.updated_at:=now();return new;end$$;create trigger engineering_revenue_projections_validate before insert or update on public.engineering_revenue_projections for each row execute function public.validate_engineering_revenue_projection();revoke all on function public.validate_engineering_revenue_projection() from public,anon,authenticated;
create view public.engineering_revenue_forecast with(security_invoker=true) as select p.tenant_id,p.company_id,p.work_id,w.name work_name,p.contract_id,c.contract_number,p.competence,p.projected_amount,'future_projection'::text source_kind from public.engineering_revenue_projections p join public.works w on w.tenant_id=p.tenant_id and w.company_id=p.company_id and w.id=p.work_id join public.engineering_contracts c on c.tenant_id=p.tenant_id and c.company_id=p.company_id and c.id=p.contract_id where p.status='active';
commit;